import {emptyCosts,validateCosts,costUnits,unitCost,recipeCost,mergeCostIngredients} from './cost-model.js?v=20261030-cost-merge-v3';
export function createCostView({$,$$,esc,read,write,toast,rerender,download,today}){
 let tab='recipes',query='',category='',editing=null,importNotice="";
 const state=()=>read('costs',emptyCosts());
 const money=n=>n===null?'미입력':n.toLocaleString('ko-KR',{maximumFractionDigits:2})+'원';
 const qty=n=>n.toLocaleString('ko-KR',{maximumFractionDigits:4});
 const pct=n=>n===null?'—':(n*100).toFixed(1)+'%';
 const id=()=>crypto.randomUUID();
 function save(s){validateCosts(s);if(!write('costs',s))return false;return true;}
 function status(c){return c.missing.length?'<span class="badge cost-warning">재료 단가 입력 필요</span>':c.rate===null?'<span class="badge">판매가 입력 필요</span>':c.overTarget?'<span class="badge cost-warning">목표 원가율 초과</span>':'<span class="badge cost-ready">계산 완료</span>';}
 function render(){const s=state(),costs=s.recipes.map(r=>recipeCost(r,s.ingredients));
 const shown=(tab==='recipes'?s.recipes:s.ingredients).filter(x=>x.name.toLowerCase().includes(query.toLowerCase())&&(!category||tab==='ingredients'||x.category===category));
 return `<div class="cost-page"><div class="hero"><div><div class="hero-tag">MENU COST MANAGEMENT</div><h2>재료 단가부터 메뉴 한 개의 원가까지.</h2><p>재료를 등록하고 배합을 입력하세요. 매입가가 바뀌면 모든 연결 메뉴의 원가가 자동으로 계산됩니다.</p></div><button class="btn cyan" data-cost-add="ingredient">＋ 재료 등록</button></div>
 <div class="kpis">${[['등록 재료',s.ingredients.length+'개','포장재도 재료로 함께 관리'],['등록 메뉴',s.recipes.length+'개','음료·디저트·베이커리'],['원가 계산 가능',costs.filter(c=>c.perUnit!==null).length+'개','배합과 재료 단가 입력 완료'],['목표 원가율 초과',costs.filter(c=>c.overTarget).length+'개','목표를 설정한 메뉴 기준']].map(([t,v,d])=>`<article class="card kpi"><div class="kpi-top">${t}<span class="kpi-icon">${t==='등록 재료'?'▦':'◫'}</span></div><div class="kpi-value">${v}</div><div class="kpi-foot">${d}</div></article>`).join('')}</div>
 <div class="filters cost-toolbar"><div class="segmented"><button data-cost-tab="recipes" class="${tab==='recipes'?'selected':''}">메뉴·레시피</button><button data-cost-tab="ingredients" class="${tab==='ingredients'?'selected':''}">재료 단가</button></div><button class="btn primary" data-cost-add="${tab==='recipes'?'recipe':'ingredient'}">＋ ${tab==='recipes'?'레시피':'재료'} 등록</button><button class="btn cyan" id="costMerge">↑ 재료 추가 가져오기</button><input id="costMergeFile" type="file" accept=".json,application/json" hidden><button class="btn" id="costBackup">↓ 원가 자료 백업</button><button class="btn" id="costRestore">↑ 원가 자료 복원</button><input id="costRestoreFile" type="file" accept=".json,application/json" hidden></div>
 ${importNotice?`<div class="note" role="status">${esc(importNotice)}</div>`:""}<section class="card"><div class="card-head"><div><h3>${tab==='recipes'?'메뉴별 원가':'재료·포장재 매입단가'}</h3><div class="sub">${tab==='recipes'?'개당 원가 = 전체 배합 원가 ÷ 판매 가능 수량':'기준단가 = 매입금액 ÷ (기준 단위 매입 수량 × 사용 가능 비율)'}</div></div></div><div class="cost-search"><input id="costSearch" aria-label="메뉴 또는 재료 검색" placeholder="${tab==='recipes'?'메뉴':'재료'}명 검색" value="${esc(query)}">${tab==='recipes'?`<select id="costCategory" aria-label="메뉴 분류"><option value="">전체 분류</option>${['음료','디저트','베이커리'].map(x=>`<option ${category===x?'selected':''}>${x}</option>`).join('')}</select>`:''}</div>
 ${!shown.length?`<div class="empty"><h3>${query||category?'검색 결과가 없습니다.':tab==='recipes'?'첫 메뉴의 레시피를 등록해 주세요.':'첫 재료의 매입단가를 등록해 주세요.'}</h3><p>${query||category?'검색어나 분류를 변경해 주세요.':tab==='recipes'?'재료 선택, 배합 사용량, 판매 가능 수량을 입력하면 원가가 계산됩니다.':'원두, 우유, 밀가루, 버터와 컵·봉투 등 포장재를 등록할 수 있습니다.'}</p>${!query&&!category?`<button class="btn primary" data-cost-add="${tab==='recipes'?'recipe':'ingredient'}">＋ ${tab==='recipes'?'레시피':'재료'} 등록</button>`:''}</div>`:
 `<div class="table-wrap"><table class="cost-table"><thead><tr>${(tab==='recipes'?['메뉴명','분류','판매가','개당 원가','원가율 / 목표','입력 상태','관리']:['재료명','매입 규격','매입금액','사용 가능 비율','기준단가','사용 메뉴','관리']).map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${shown.map(x=>{if(tab==='recipes'){const c=recipeCost(x,s.ingredients);return `<tr><td><strong>${esc(x.name)}</strong><small>1배합 ${qty(x.output)}개 · 재료 ${x.lines.length}종</small></td><td>${x.category}</td><td>${money(x.salePrice)}</td><td><strong>${c.perUnit===null?'계산 대기':money(c.perUnit)}</strong></td><td class="${c.overTarget?'negative':''}">${pct(c.rate)}<small>목표 ${pct(x.target)}</small></td><td>${status(c)}</td><td><button class="btn small" data-cost-edit="recipe" data-id="${esc(x.id)}">상세·수정</button></td></tr>`;}const cost=unitCost(x);return `<tr><td><strong>${esc(x.name)}</strong><small>${esc(x.supplier||'거래처 미입력')}</small></td><td>${qty(x.packQty)} ${x.unit}</td><td>${money(x.price)}</td><td>${pct(x.yield)}</td><td>${cost===null?'<span class="badge cost-warning">매입가 입력 필요</span>':`${cost.toLocaleString('ko-KR',{maximumFractionDigits:4})}원 / ${costUnits[x.unit].base}`}</td><td>${s.recipes.filter(r=>r.lines.some(l=>l.ingredientId===x.id)).length}개</td><td><button class="btn small" data-cost-edit="ingredient" data-id="${esc(x.id)}">수정</button></td></tr>`;}).join('')}</tbody></table></div>`}</section>
 <div class="cost-help"><p>재료비와 포장비 기준입니다. 인건비·임대료·결제 및 배달 수수료는 포함하지 않습니다. 매입가와 판매가의 부가세 포함 기준을 통일해 주세요.</p><p>현재 기기·브라우저에 자동 저장됩니다. 다른 기기와 공유되지 않으며, 데이터 관리의 전체 백업·복원에도 원가 자료가 포함됩니다.</p></div>
 <dialog id="costDialog" class="cost-dialog"><form id="costForm"></form></dialog></div>`;}
 const field=(label,name,value,type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;
 function ingredientOptions(items,selected,filtered=false){return `<option value="">재료 선택</option>${items.map(i=>`<option value="${esc(i.id)}" ${selected===i.id?"selected":""}>${esc(i.name)}${filtered&&selected===i.id?" (현재 선택)":""}</option>`).join("")}`;}
 function lineHTML(line={ingredientId:"",qty:""}){return `<div class="cost-line"><div class="cost-picker"><label>재료 검색<input class="cost-ingredient-search" type="search" aria-label="재료명 검색" placeholder="재료명 검색" autocomplete="off" maxlength="200"></label><select class="cost-ingredient" aria-label="재료 선택" required>${ingredientOptions(state().ingredients,line.ingredientId)}</select><small class="cost-search-status" role="status"></small></div><label>배합 사용량<input class="cost-qty" aria-label="배합 사용량" type="number" min="0" step="any" required value="${esc(line.qty)}"></label><span class="cost-line-unit"></span><strong class="cost-line-total">—</strong><button class="iconbtn cost-remove-line" type="button" aria-label="재료 행 삭제">×</button></div>`;}
 function filterIngredientRow(row){const search=row.querySelector(".cost-ingredient-search"),select=row.querySelector(".cost-ingredient"),selected=select.value;const normalize=v=>v.normalize("NFKC").replace(/\s+/g,"").toLowerCase(),term=normalize(search.value);const all=state().ingredients,matched=all.filter(i=>normalize(i.name).includes(term));const retained=all.find(i=>i.id===selected&&!matched.some(m=>m.id===i.id));select.innerHTML=ingredientOptions(retained?[retained]:[],selected,true)+matched.map(i=>`<option value="${esc(i.id)}" ${selected===i.id?"selected":""}>${esc(i.name)}</option>`).join("");select.value=selected;row.querySelector(".cost-search-status").textContent=term?matched.length?`검색 결과 ${matched.length}개${retained?" · 현재 선택 유지":""}`:`검색 결과 없음${retained?" · 현재 선택 유지":""}`:"";}
 function open(kind,existingId){const s=state(),x=(kind==='ingredient'?s.ingredients:s.recipes).find(x=>x.id===existingId);editing={kind,id:x?.id};const f=$('#costForm');f.innerHTML=`<div class="dialog-head"><div><h2>${kind==='ingredient'?'재료 단가':'메뉴 레시피'} ${x?'수정':'등록'}</h2><p>${kind==='ingredient'?'매입 규격을 입력하면 g·ml·개·샷·잔당 단가가 계산됩니다.':'음료는 1잔 기준, 베이커리는 한 배치 기준으로 입력하세요.'}</p></div><button type="button" class="iconbtn" id="costClose" aria-label="닫기">×</button></div>`+
 (kind==='ingredient'?`${field('재료·포장재명','name',x?.name,'text','required maxlength="200" placeholder="예: 무염버터"')}<div class="formgrid">${field('매입 수량','packQty',x?.packQty,'number','required min="0.000001" step="any" placeholder="예: 1"')}<label>매입 단위<select name="unit">${Object.keys(costUnits).map(u=>`<option ${x?.unit===u?'selected':''}>${u}</option>`).join('')}</select></label></div><div class="formgrid">${field('매입금액 (원, 모르면 공란)','price',x?.price,'number','min="0" step="any" placeholder="예: 18000"')}${field('사용 가능 비율 (%)','yield',x?x.yield*100:100,'number','required min="0.000001" max="100" step="any"')}</div><div id="costMaterialPreview" class="cost-preview" aria-live="polite"></div>${field('거래처 (선택)','supplier',x?.supplier,'text','maxlength="300"')}${field('매입일·규격 등 메모 (선택)','note',x?.note,'text','maxlength="1000"')}`:
 `${field('메뉴명','name',x?.name,'text','required maxlength="200" placeholder="예: 휘낭시에"')}<div class="formgrid"><label>분류<select name="category">${['음료','디저트','베이커리'].map(c=>`<option ${x?.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${field('판매가 (원, 선택)','salePrice',x?.salePrice,'number','min="0.000001" step="any"')}</div><div class="formgrid">${field('한 배합의 판매 가능 수량','output',x?.output??1,'number','required min="0.000001" step="any"')}${field('목표 원가율 (%, 선택)','target',x?.target?x.target*100:null,'number','min="0.000001" max="100" step="any"')}</div><p class="explain">재료 사용량은 재료의 기준 단위(g·ml·개·샷·잔)로 입력하세요. 예: 반죽 전체로 20개를 판매할 수 있다면 수량은 20입니다. 포장재도 20개 기준으로 입력하세요.</p><div id="costLines">${(x?.lines||[{}]).map(lineHTML).join('')}</div><button class="btn small" type="button" id="costAddLine">＋ 재료 추가</button><div class="cost-preview" id="costRecipePreview" aria-live="polite"></div><label>제조·보관 메모 (선택)<textarea name="note" maxlength="1000">${esc(x?.note||'')}</textarea></label>`)+
 `<div id="costFormError" class="cost-form-error" role="alert"></div><div class="cost-dialog-actions">${x?'<button type="button" class="btn danger" id="costDelete">삭제</button>':''}<button type="button" class="btn" id="costCancel">취소</button><button class="btn primary" type="submit">${kind==='ingredient'?'재료 저장':'레시피 저장'}</button></div>`;
 $('#costClose').onclick=$('#costCancel').onclick=()=>$('#costDialog').close();
 f.oninput=e=>{if(e.target.matches(".cost-ingredient-search")){filterIngredientRow(e.target.closest(".cost-line"));return;}preview();};f.onkeydown=e=>{if(e.key==="Enter"&&e.target.matches(".cost-ingredient-search")){e.preventDefault();e.target.closest(".cost-line").querySelector(".cost-ingredient").focus();}};f.onchange=e=>{if(e.target.matches(".cost-ingredient"))filterIngredientRow(e.target.closest(".cost-line"));preview();};f.onclick=e=>{if(e.target.closest('.cost-remove-line')){e.target.closest('.cost-line').remove();preview();}};
 if(kind==='recipe')$('#costAddLine').onclick=()=>{$('#costLines').insertAdjacentHTML('beforeend',lineHTML());preview();};
 if(x)$('#costDelete').onclick=()=>{const fresh=state();if(kind==='ingredient'&&fresh.recipes.some(r=>r.lines.some(l=>l.ingredientId===x.id))){$('#costFormError').textContent='사용 중인 재료입니다. 레시피에서 이 재료를 제거하거나 교체한 뒤 삭제해 주세요.';return;}if(!confirm(`${x.name}을(를) 삭제할까요?`))return;fresh[kind==='ingredient'?'ingredients':'recipes']=fresh[kind==='ingredient'?'ingredients':'recipes'].filter(i=>i.id!==x.id);if(save(fresh)){$('#costDialog').close();rerender();toast('삭제했습니다.');}};
 f.onsubmit=e=>{e.preventDefault();try{const fresh=state(),item=collect(),key=kind==='ingredient'?'ingredients':'recipes';if(kind==='ingredient'&&fresh.ingredients.some(i=>i.id!==item.id&&i.name.trim().toLowerCase()===item.name.toLowerCase()))throw Error('같은 이름의 재료가 있습니다. 규격이나 거래처를 이름에 추가해 구분하세요.');const index=fresh[key].findIndex(i=>i.id===item.id);index<0?fresh[key].push(item):fresh[key].splice(index,1,item);if(save(fresh)){$('#costDialog').close();rerender();toast(kind==='ingredient'?'재료를 저장하고 연결 메뉴 원가를 갱신했습니다.':'레시피를 저장했습니다.');}}catch(e){$('#costFormError').textContent=e.message;}};
 $('#costDialog').showModal();preview();}
 function collect(){const f=$('#costForm'),v=n=>f.elements.namedItem(n).value,optional=n=>v(n)===''?null:Number(v(n));const item={id:editing.id||id(),name:v('name').trim(),note:v('note').trim()};return editing.kind==='ingredient'?{...item,unit:v('unit'),packQty:Number(v('packQty')),price:optional('price'),yield:Number(v('yield'))/100,supplier:v('supplier').trim()}:{...item,category:v('category'),output:Number(v('output')),salePrice:optional('salePrice'),target:optional('target')===null?null:optional('target')/100,lines:$$('#costLines .cost-line').map(row=>({ingredientId:row.querySelector('select').value,qty:row.querySelector('.cost-qty').value===''?NaN:Number(row.querySelector('.cost-qty').value)}))};}
 function preview(){const item=collect();if(editing.kind==='ingredient'){const valid=item.packQty>0&&item.yield>0&&item.yield<=1&&item.price!==null;$('#costMaterialPreview').textContent=valid?`기준단가 ${unitCost(item).toLocaleString('ko-KR',{maximumFractionDigits:4})}원 / ${costUnits[item.unit].base}`:'매입 수량·금액·사용 가능 비율을 입력하면 단가가 표시됩니다.';return;}
 const s=state(),rows=$$('#costLines .cost-line');let complete=item.lines.length>0&&item.output>0;let total=0;
 rows.forEach((row,n)=>{const l=item.lines[n],i=s.ingredients.find(i=>i.id===l.ingredientId),u=i?unitCost(i):null;row.querySelector('.cost-line-unit').textContent=i?costUnits[i.unit].base:'';const valid=u!==null&&Number.isFinite(l.qty)&&l.qty>=0;row.querySelector('.cost-line-total').textContent=valid?money(u*l.qty):'입력 필요';if(valid)total+=u*l.qty;else complete=false;});
 $('#costRecipePreview').innerHTML=complete?`<div><span>전체 배합 원가</span><strong>${money(total)}</strong></div><div><span>개당 원가</span><strong>${money(total/item.output)}</strong></div><div><span>판매가 대비 원가율</span><strong>${item.salePrice>0?pct(total/item.output/item.salePrice):'판매가 입력 필요'}</strong></div>`:'재료·사용량·판매 가능 수량을 입력하면 원가가 표시됩니다. 매입가가 비어 있는 재료는 재료 단가에서 먼저 입력해 주세요.';}
 function bind(){$("#costMerge").onclick=()=>$("#costMergeFile").click();$("#costMergeFile").onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error("파일은 5MB 이하로 올려 주세요.");const b=JSON.parse(await file.text());if(b.kind!=="ikovox-costs")throw Error("원가 자료 JSON 파일을 선택해 주세요.");const merged=mergeCostIngredients(state(),b.costs);if(save(merged.state)){tab="ingredients";query="";category="";importNotice=`재료 ${merged.added}개를 추가했습니다. 기존 레시피는 유지했습니다.${merged.skipped.length?` 같은 이름의 재료 ${merged.skipped.length}개는 기존 입력값을 유지했습니다: ${merged.skipped.slice(0,5).join(", ")+(merged.skipped.length>5?` 외 ${merged.skipped.length-5}개`:"")}`:""}`;rerender();toast("재료 추가 가져오기를 완료했습니다.");}}catch(e){toast("가져오기 실패: "+e.message);}};$("#costRestore").onclick=()=>$("#costRestoreFile").click();$("#costRestoreFile").onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error("파일은 5MB 이하로 올려 주세요.");const b=JSON.parse(await file.text());if(b.kind!=="ikovox-costs")throw Error("원가 자료 백업 파일을 선택해 주세요.");validateCosts(b.costs);if(!confirm("현재 재료 단가와 레시피를 백업 내용으로 교체할까요?"))return;if(save(b.costs)){rerender();toast("원가 자료를 복원했습니다.");}}catch(e){toast("복원 실패: "+e.message);}};$$('[data-cost-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.costTab;query='';category='';rerender();});$$('[data-cost-add]').forEach(b=>b.onclick=()=>{if(b.dataset.costAdd==='recipe'&&!state().ingredients.length){toast('레시피에 사용할 재료를 먼저 등록해 주세요.');open('ingredient');return;}open(b.dataset.costAdd);});$$('[data-cost-edit]').forEach(b=>b.onclick=()=>open(b.dataset.costEdit,b.dataset.id));$('#costSearch').oninput=e=>{if(e.isComposing)return;const pos=e.target.selectionStart;query=e.target.value;rerender();$('#costSearch').focus();$('#costSearch').setSelectionRange(pos,pos);};if($('#costCategory'))$('#costCategory').onchange=e=>{category=e.target.value;rerender();};$('#costBackup').onclick=()=>download('이코복스_원가백업_'+today+'.json',JSON.stringify({kind:'ikovox-costs',costs:state()},null,2),'application/json');}
 return {render,bind,addRecipe:()=>{if(!state().ingredients.length){toast('재료를 먼저 등록해 주세요.');open('ingredient');}else open('recipe');}};
}
